          ),
          local!datosGestionesPrecargados: if(
            length(local!posGestionPrecargada) > 0,
            index(
              index(
                local!gestionesPrecargadas,
                index(local!posGestionPrecargada, 1, 0),
                null
              ),
              "g",
              null
            ),
            null
          ),
          local!estadoTxt: if(
            a!isNotNullOrEmpty(local!estCore),
            #"_a-0000f069-4f37-8000-9cc8-011c48011c48_20052795"(
              estadoSolicitud: local!estCore,
              datosGestiones: if(
                #"_a-0000f09f-42ed-8000-9d42-011c48011c48_5644032",
                local!datosGestionesPrecargados,
                #"_a-0000f069-4f37-8000-9cc8-011c48011c48_20051122"(
                codSolicitud: tostring(
                  index(
                    fv!row,
                    #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/f2b6f90b-183b-493e-81c1-d1dd65a6cbd9",
                    null
                  )
                )
              )
              )
            ),
            #"_a-0000f069-4f37-8000-9cc8-011c48011c48_20063670"(
