                #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/65f4378b-cf90-4761-b1d0-16ace177a82c",
                null
              )
            )
          ),
          #"SYSTEM_SYSRULES_tagField"(
            tags: #"SYSTEM_SYSRULES_tagItem"(
              text: local!estadoTxt,
              backgroundColor: #"_a-0000f069-4f37-8000-9cc8-011c48011c48_20063676"(estado: local!estadoTxt),
              textColor: #"_a-0000f099-f136-8000-9d3c-011c48011c48_5624184"
            ),
            align: "CENTER"
          )
        ),
        sortField: #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/65f4378b-cf90-4761-b1d0-16ace177a82c"
      ),
      #"SYSTEM_SYSRULES_gridColumn"(
        label: "Fecha solicitud",
        value: a!localVariables(
          /* Paridad SCA_BuscadorTabla: la fila de CORE (consultarUltimaGestion) manda; el record SCA2 es respaldo */
          local!posCore: if(
            a!isNullOrEmpty(local!ultimasIds),
            {},
            wherecontains(
              tostring(
                index(
                  fv!row,
                  #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/f2b6f90b-183b-493e-81c1-d1dd65a6cbd9",
                  null
                )
              ),
              touniformstring(local!ultimasIds)
            )
          ),
          local!coreRow: if(
            length(local!posCore) > 0,
            index(
              local!ultimas,
              index(local!posCore, 1, 0),
              null
