            #"urn:appian:record-field:v1:9a9209c7-aab4-4078-9bef-280de47fdd6e/78fc061f-12bd-441e-aa55-dcff066af9fe",
            null
          ),
          if(
            a!isNotNullOrEmpty(local!fecSolCore),
            tostring(local!fecSolCore),
            if(
              a!isNotNullOrEmpty(local!fecCore),
              tostring(local!fecCore),
              if(
                a!isNullOrEmpty(
                  index(
                    fv!row,
                    #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/331a1fda-174e-4caf-976e-0e259856800f",
                    null
                  )
                ),
                "-",
                text(
                  index(
                    fv!row,
                    #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/331a1fda-174e-4caf-976e-0e259856800f",
                    null
                  ),
                  "dd/MM/yyyy HH:mm:ss"
                )
              )
            )
          )
        ),
        sortField: #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/331a1fda-174e-4caf-976e-0e259856800f"
      ),
      #"SYSTEM_SYSRULES_gridColumn"(
        label: "Número póliza",
        value: index(
