          #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/ea9a37fd-f033-4f83-ad3d-55d6d4a8ae7b",
          null
        ),
        sortField: #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/ea9a37fd-f033-4f83-ad3d-55d6d4a8ae7b"
      ),
      #"SYSTEM_SYSRULES_gridColumn"(
        label: "Línea negocio",
        value: if(
          a!isNullOrEmpty(
            index(
              fv!row,
              #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/2242a3b0-3166-45d7-91fc-3082f21a1a34",
              null
            )
          ),
          "-",
          index(
            #"_a-0000f069-4f37-8000-9cc8-011c48011c48_20050695",
            tointeger(
              index(
                fv!row,
                #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/2242a3b0-3166-45d7-91fc-3082f21a1a34",
                null
              )
            ),
            "-"
          )
        ),
        sortField: #"urn:appian:record-field:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/2242a3b0-3166-45d7-91fc-3082f21a1a34"
      ),
      #"SYSTEM_SYSRULES_gridColumn"(
        label: "Causa anulación",
        value: a!localVariables(
          /* Paridad SCA_BuscadorTabla: la fila de CORE (consultarUltimaGestion) manda; el record SCA2 es respaldo */
          local!posCore: if(
            a!isNullOrEmpty(local!ultimasIds),
            {},
            wherecontains(
