            #"urn:appian:record-field:v1:9a9209c7-aab4-4078-9bef-280de47fdd6e/d3ea438a-426e-4524-b46c-052fb101097d",
            null
          ),
          if(
            a!isNotNullOrEmpty(local!codCausaCore),
            proper(
              a!defaultValue(
                index(
                  #"_a-0000f069-4f37-8000-9cc8-011c48011c48_20050611",
