                "-"
              )
            ),
            proper(
              if(
                a!isNullOrEmpty(local!codCausa),
                a!defaultValue(
                  index(
                    index(
                      index(
                        fv!row,
                        #"urn:appian:record-relationship:v1:c531595c-c3b5-454c-a355-8145e7e27e9a/63161335-1bdd-4c7a-82eb-3560786a41d5",
                        {}
