                      1,
                      null
                    ),
                    #"urn:appian:record-field:v1:9a9209c7-aab4-4078-9bef-280de47fdd6e/b3b05401-6420-4d28-8c0a-d55c0665a687",
                    null
                  ),
                  "-"
                ),
                a!defaultValue(
                  index(
                    #"_a-0000f069-4f37-8000-9cc8-011c48011c48_20050611",
                    tointeger(local!codCausa),
                    null
                  ),
                  index(
