                  null
                )
              ),
              touniformstring(local!ultimasIds)
            )
          ),
          local!txtObs: if(
            length(local!pos) > 0,
            index(
              index(
                local!ultimas,
                index(local!pos, 1, 0),
                null
              ),
              "txtObs",
              null
            ),
            null
          ),
          if(
            a!isNotNullOrEmpty(local!txtObs),
            tostring(local!txtObs),
            a!defaultValue(
              index(
                index(
                  index(
                    fv!row,
