                    {}
                  ),
                  1,
                  null
                ),
                #"urn:appian:record-field:v1:9a9209c7-aab4-4078-9bef-280de47fdd6e/ef1b0aa7-41ee-4590-83b2-52f89c8be7f5",
                null
              ),
              "-"
            )
          )
        )
      )
    },
    pagingSaveInto: ri!pagingInfo,
    initialSorts: if(
      a!isNullOrEmpty(ri!totalCount),
